        tags.length!==1||tags[0]!==ownerAmazonTag||
        keys.length!==new Set(keys).size||
        keys.some(key=>!['k','tag'].includes(key)))return;
      try {window.umami.track('amazon-search:'+id)}catch{/* best effort */}
      return;
    }
    if(!asinPattern.test(target.pathname)||keys.length!==new Set(keys).size||
      keys.some(key=>!['tag','th','psc'].includes(key)))return;
    if(!Object.hasOwn(exactAmazonAsinByModel,id)||
       target.pathname!=='/dp/'+exactAmazonAsinByModel[id])return;
    let trackingName;
    if(hasTag){
      // Only our own affiliate tag with an explicit "sponsored" disclosure
      // is counted as a paid exit. Wrong tags are ignored rather than counted
      // under a misleading monetization metric.
      if(tags.length!==1||tags[0]!==ownerAmazonTag||!sponsored)return;
      trackingName='amazon:'+id+':'+placement; // preserve historical paid series
    }else{
      if(sponsored)return; // inconsistent link attribution
      // Unpaid product exits remain useful but cannot inflate paid activity.
      trackingName='amazon-unpaid:'+id+':'+placement;
    }
    if(trackingName.length>55)return;
    try {window.umami.track(trackingName)}catch{/* Navigation cannot depend on analytics. */}
  },{capture:true,passive:true});
})();

'use strict';
(() => {
  const $ = (id) => document.getElementById(id);
  // Never transmit private messages or email addresses to any backend.
  const launcher = $('chatLauncher');
  const panel = $('chatPanel');
  const close = $('chatClose');
  const history = $('chatHistory');
  const form = $('chatForm');
  const input = $('chatInput');
  const topics = $('chatTopics');
  if (!launcher || !panel || !close || !history || !form || !input || !topics) return;

  const affiliate = document.body?.dataset?.experience === "affiliate";
  const replies = Object.freeze([
    { pattern: /bonjour|salut|hello|bonsoir/i, answer:"Bonjour ! Je peux vous aider à choisir une montre, comprendre les tailles, comparer les modèles et savoir où acheter." },
    { pattern: /prix|tarif|combien|coût|euros?|payer|achat/i, answer: affiliate ? "Les prix varient selon les marchands. Retrouvez 52 montres, dont 15 comparées en profondeur, avec leurs références exactes et les liens fabricants ou Amazon.fr. Certains liens Amazon sont rémunérés et clairement identifiés. Aucun paiement ne se fait sur Atelier Montres." : "La boutique n'est pas encore ouverte : aucun prix de vente n'est fixé et aucun paiement n'est accepté sur cette vitrine. Nous étudions actuellement des modèles, puis nous confirmerons les tarifs réels." },
    { pattern: /livrai|colis|expédi|expedition|envoi|délai|transport|mon colis|suivi/i, answer: affiliate ? "Pour ces modèles multimarques, les achats et livraisons sont gérés par le marchand chez lequel vous commandez, pas par Atelier Montres. Vérifiez les frais, délais et zones de livraison auprès de chaque vendeur, notamment pour la France." : "Nous prévoyons un petit stock contrôlé et des expéditions préparées en France. Les destinations, transporteurs, frais et délais précis seront publiés après validation : je ne peux pas promettre une date ou un coût aujourd'hui." },
    { pattern: /garanti|retour|rembour|rétract|sav|casse|panne/i, answer: affiliate ? "Pour la sélection multimarque, les commandes, retours et garanties sont traités par le vendeur externe. En France, la vente à distance aux consommateurs comporte en principe un droit de rétractation de 14 jours, sous réserve des exceptions légales. Consultez ses CGV." : "Les conditions de retour et le service après-vente seront publiés avant le lancement. Les droits légaux des consommateurs en France restent applicables, notamment la rétractation en principe pendant 14 jours pour l'achat à distance et la garantie légale de conformité." },
    { pattern: /marque|logo|personnalis|cadran|matériau|saphir|acier|mouvement|quartz/i, answer: affiliate ? "Notre sélection documente 52 montres notamment Casio, SKMEI, Citizen, Seiko, Tissot, Orient et Hamilton. Les images générées par IA sont indiquées comme non contractuelles ; vérifiez toujours la vraie photographie et la variante auprès du vendeur." : "Nous recherchons des montres à quartz au rendu soigné, idéalement sans logo de tiers, avec la possibilité d'imprimer notre identité en usine. Les matériaux et caractéristiques seront affichés seulement une fois confirmés sur les modèles réellement sélectionnés." },
    { pattern: /newsletter|actualité|nouveauté|inscri|abonn|mail/i, answer:"La newsletter n'est pas proposée actuellement. Vous pouvez retrouver les nouveautés directement dans notre catalogue de montres." },
    { pattern: /commande|panier|stock|disponible|acheter|boutique|ouvrir|ouverture/i, answer: affiliate ? "Vous pouvez explorer 52 montres et comparer jusqu’à trois références. Les commandes sont passées exclusivement chez les marchands externes. Certains liens Amazon.fr peuvent être rémunérés ; vérifiez le modèle, la variante, le prix et les conditions du vendeur avant tout achat." : "La collection est en préparation. Il n'y a actuellement ni catalogue actif ni commande possible. Les futurs achats seront sécurisés par une plateforme de paiement séparée, lorsque le commerce sera prêt." },
    { pattern: /taille|poignet|diamètre|bracelet|mesure/i, answer:"Pour choisir une montre, mesurez votre poignet avec un mètre ruban souple. Notre conseiller vous aide à filtrer les modèles par diamètre ; les dimensions manquantes sont signalées plutôt qu'estimées." },
    { pattern: /contact|écrire|humain|responsable|email|téléphone/i, answer:"Les coordonnées professionnelles ne sont pas encore publiées dans nos informations légales. Ce guide est automatique et n'est relié à aucun conseiller humain : ne lui transmettez pas de données personnelles." }
  ]);
  const reply = (message) => {
    const trimmed = String(message || '').normalize('NFKC').slice(0,280);
    for (const answer of replies) if (answer.pattern.test(trimmed)) return answer.answer;
    return "Je suis un assistant d'information local, pas un conseiller en direct. Je peux répondre sur les prix, les montres, les stocks, la livraison, les garanties, le guide des tailles et la newsletter. Essayez une de ces catégories.";
  };
  const addMessage = (message, author) => {
    const line = document.createElement('p');
    line.className = 'chat-bubble' + (author === 'user' ? ' user' : '');
    line.textContent = message;
    history.appendChild(line);
    while (history.children.length > 32) history.firstElementChild.remove();
    history.scrollTop = history.scrollHeight;
  };
  const ask = (message) => {
    const clean = String(message).trim().slice(0,280);
    if (!clean) return;
    addMessage(clean, 'user');
    addMessage(reply(clean), 'bot');
  };
  const open = () => {
    panel.hidden = false;
    launcher.setAttribute('aria-expanded', 'true');
    if (!history.children.length) addMessage("Bienvenue chez Atelier Montres. Comment puis-je vous renseigner ?", 'bot');
    input.focus();
  };
  const hide = () => {
    panel.hidden = true;
    launcher.setAttribute('aria-expanded', 'false');
    launcher.focus();
  };
  launcher.addEventListener('click', () => panel.hidden ? open() : hide());
  close.addEventListener('click', hide);
  document.addEventListener('keydown', (event) => { if (event.key === 'Escape' && !panel.hidden) hide(); });
  form.addEventListener('submit', (event) => {
    event.preventDefault();
    ask(input.value);
    input.value = '';
    input.focus();
  });
  topics.addEventListener('click', (event) => {
    const btn = event.target.closest('button[data-question]');
    if (btn) ask(btn.getAttribute('data-question') || '');
  });
  // Newsletter subscriptions are hosted by a verified external provider.
  // No email addresses are ever collected by this static website.
  fetch('./config.json', {cache:'no-store'})
    .then((response) => {
      if (!response.ok) throw new Error('Configuration inaccessible');
      return response.json();
    })
    .then((settings) => {
      const urlValue = settings?.newsletterUrl;
      if (typeof urlValue !== 'string') return;
      const url = new URL(urlValue);
      const host = url.hostname.toLowerCase();
      const allowed = host === 'sibforms.com' || host.endsWith('.sibforms.com') ||
        host === 'buttondown.com' || host.endsWith('.buttondown.com') ||
        host === 'brevo.com' || host.endsWith('.brevo.com');
      if (url.protocol !== 'https:' || !allowed) return;
      const link = $('newsletterCta');
      const inactive = $('newsletterComing');
      if (!link || !inactive) return;
      link.href = url.href;
      link.hidden = false;
      inactive.hidden = true;
      const section = $('newsletter');
      if (section) section.hidden = false;
    })
    .catch(() => { /* Prelaunch remains disabled; never claim a subscription. */ });
})();
